mapper.select:
SELECT 
FROM model_provider

    AND del_flag = 0

        AND provider_name LIKE CONCAT('%', #{bo.providerName}, '%')


        AND provider_code LIKE CONCAT('%', #{bo.providerCode}, '%')


        AND provider_icon = #{bo.providerIcon}


        AND provider_desc = #{bo.providerDesc}


        AND api_host = #{bo.apiHost}


        AND status = #{bo.status}


        AND sort_order = #{bo.sortOrder}


        AND update_ip = #{bo.updateIp}


ORDER BY id ASC

SELECT EXISTS(
    SELECT 1
    FROM model_provider
    WHERE provider_code = #{providerCode}
    AND del_flag = #{normalDelFlag}

        AND id != #{excludeId}

)

SELECT id, provider_name, provider_code, provider_icon, provider_desc, api_host,
       status, sort_order, remark, version, del_flag, update_ip,
       create_dept, create_by, create_time, update_by, update_time
FROM model_provider
WHERE provider_code = #{providerCode}
  AND status = #{normalStatus}
  AND del_flag = #{normalDelFlag}
LIMIT 1
